public class Main {
    public static String countUp(int n) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < n; i++) {
            b.append(i);
        }
        return b.toString();
    }
    public static void main(String[] args) {
        System.out.println(countUp(3));
    }
}

